package com.hospital.smartqueue.doctor.scheduling.domain;
import jakarta.persistence.*; import org.hibernate.annotations.UuidGenerator; import java.time.*; import java.util.*;
@Entity @Table(name="schedule_working_periods") public class WorkingPeriod { @Id @GeneratedValue @UuidGenerator private UUID id; @ManyToOne @JoinColumn(name="schedule_revision_id") private DoctorScheduleRevision schedule; @Column(name="day_of_week") private int dayOfWeek; @Column(name="start_time") private LocalTime start; @Column(name="end_time") private LocalTime end; @OneToMany(mappedBy="period",cascade=CascadeType.ALL,orphanRemoval=true) private List<ScheduleBreak> breaks=new ArrayList<>(); protected WorkingPeriod(){} public WorkingPeriod(DoctorScheduleRevision s,int day,LocalTime start,LocalTime end){this.schedule=s;this.dayOfWeek=day;this.start=start;this.end=end;} public int day(){return dayOfWeek;} public LocalTime start(){return start;} public LocalTime end(){return end;} public List<ScheduleBreak> breaks(){return List.copyOf(breaks);} public void add(ScheduleBreak b){breaks.add(b);} }
